declare_lint ! { #[doc = " The `suspicious_double_ref_op` lint checks for usage of `.clone()`/`.borrow()`/`.deref()`"] #[doc = " on an `&&T` when `T: !Deref/Borrow/Clone`, which means the call will return the inner `&T`,"] #[doc = " instead of performing the operation on the underlying `T` and can be confusing."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![allow(unused)]"] #[doc = " struct Foo;"] #[doc = " let foo = &&Foo;"] #[doc = " let clone: &Foo = foo.clone();"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Since `Foo` doesn't implement `Clone`, running `.clone()` only dereferences the double"] #[doc = " reference, instead of cloning the inner type which should be what was intended."] pub SUSPICIOUS_DOUBLE_REF_OP , Warn , "suspicious call of trait method on `&&T`" }